import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Calendar } from 'lucide-react';

const massageTypes = [
  { id: 'relaxing', name: 'Relajante' },
  { id: 'decontracting', name: 'Descontracturante' },
  { id: 'lymphatic', name: 'Drenaje Linfático' },
  { id: 'shiatsu', name: 'Shiatsu Lumbar' },
  { id: 'hot_stone', name: 'Hot Stone Premium' },
];

const durations = [
  { value: '30', label: '30 Minutos' },
  { value: '60', label: '60 Minutos' },
  { value: '90', label: '90 Minutos' },
];

export default function BookingModal({ isOpen, onClose, initialType }) {
  const [selectedType, setSelectedType] = useState(initialType || 'relaxing');
  const [selectedDuration, setSelectedDuration] = useState('60');

  // Set the initial type when modal opens
  if (isOpen && initialType && selectedType !== initialType) {
      setSelectedType(initialType);
  }

  const handleBook = () => {
    const typeName = massageTypes.find(t => t.id === selectedType)?.name;
    const message = `Hola! Me gustaría reservar un masaje ${typeName} de ${selectedDuration} minutos en mi hotel. Quedo atento/a para coordinar disponibilidad.`;
    const whatsappUrl = `https://wa.me/1234567890?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
    onClose();
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-black/60 backdrop-blur-sm"
          ></motion.div>

          <motion.div 
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            className="relative bg-white w-full max-w-lg rounded-sm shadow-2xl overflow-hidden"
          >
            <div className="bg-[#1a1a1a] p-6 text-center text-white relative">
              <button 
                onClick={onClose} 
                className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 hover:text-white transition-colors"
              >
                <X size={24} />
              </button>
              <h3 className="text-2xl font-serif">Reservar Masaje</h3>
            </div>

            <div className="p-8 space-y-8">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-3 uppercase tracking-wider">Tipo de Masaje</label>
                <select 
                  className="w-full border border-gray-300 p-3 bg-white focus:outline-none focus:border-[#c5a059] rounded-sm appearance-none"
                  value={selectedType}
                  onChange={(e) => setSelectedType(e.target.value)}
                >
                  {massageTypes.map(type => (
                    <option key={type.id} value={type.id}>{type.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-3 uppercase tracking-wider">Duración</label>
                <div className="grid grid-cols-3 gap-3">
                  {durations.map(duration => (
                    <button
                      key={duration.value}
                      onClick={() => setSelectedDuration(duration.value)}
                      className={`py-3 border text-sm transition-colors rounded-sm ${
                        selectedDuration === duration.value 
                        ? 'border-[#c5a059] bg-[#c5a059]/10 text-[#c5a059] font-medium' 
                        : 'border-gray-200 text-gray-600 hover:border-gray-300'
                      }`}
                    >
                      {duration.label}
                    </button>
                  ))}
                </div>
              </div>

              <div className="bg-[#f9f6f0] p-4 rounded-sm flex items-start text-sm text-gray-600">
                <Calendar className="w-5 h-5 text-[#c5a059] mr-3 shrink-0" />
                <p>Al continuar, serás redirigido a WhatsApp para confirmar la disponibilidad y horario con nuestro equipo.</p>
              </div>

              <button 
                onClick={handleBook}
                className="w-full bg-[#c5a059] hover:bg-[#b08d4b] text-white py-4 rounded-sm transition-colors duration-300 uppercase tracking-widest font-medium"
              >
                Continuar a WhatsApp
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

import { useState } from 'react';
import { motion } from 'framer-motion';

export default function ContactForm() {
  const [formData, setFormData] = useState({ name: '', hotel: '', message: '' });

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Mensaje enviado:', formData);
    // Here we could simulate sending, for now just reset
    alert('Mensaje enviado exitosamente. Nos pondremos en contacto a la brevedad.');
    setFormData({ name: '', hotel: '', message: '' });
  };

  return (
    <section id="contact" className="py-24 bg-white">
      <div className="container mx-auto px-6 md:px-12 max-w-4xl">
        <div className="text-center mb-16">
          <h2 className="text-3xl md:text-5xl font-serif text-gray-900 mb-4">Contacto</h2>
          <div className="w-16 h-0.5 bg-[#c5a059] mx-auto mb-6"></div>
          <p className="text-gray-600 font-light">
            ¿Representas a un hotel y deseas integrar nuestro servicio? ¿O eres un huésped buscando información adicional? Escríbenos.
          </p>
        </div>

        <motion.form 
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          onSubmit={handleSubmit} 
          className="space-y-6"
        >
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2 uppercase tracking-wider">Nombre Completo</label>
              <input 
                type="text" 
                required
                className="w-full border-b border-gray-300 py-3 bg-transparent focus:outline-none focus:border-[#c5a059] transition-colors"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2 uppercase tracking-wider">Hotel / Institución</label>
              <input 
                type="text" 
                className="w-full border-b border-gray-300 py-3 bg-transparent focus:outline-none focus:border-[#c5a059] transition-colors"
                value={formData.hotel}
                onChange={e => setFormData({...formData, hotel: e.target.value})}
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2 uppercase tracking-wider">Tu Mensaje</label>
            <textarea 
              required
              rows="4" 
              className="w-full border-b border-gray-300 py-3 bg-transparent focus:outline-none focus:border-[#c5a059] transition-colors resize-none"
              value={formData.message}
              onChange={e => setFormData({...formData, message: e.target.value})}
            ></textarea>
          </div>
          <div className="text-center pt-6">
            <button 
              type="submit" 
              className="bg-gray-900 hover:bg-[#c5a059] text-white px-10 py-4 transition-colors duration-300 uppercase tracking-widest text-sm font-medium"
            >
              Enviar Mensaje
            </button>
          </div>
        </motion.form>
      </div>
    </section>
  );
}

